'use client'

import { useRef } from 'react'
import type { VendorDocumentRecord, VendorDocumentRequirement } from '@/lib/vendor/documents'

export function DocumentCard({ requirement, document, onUpload }: { requirement: VendorDocumentRequirement; document: VendorDocumentRecord; onUpload: (file: File) => void }) { const inputRef = useRef<HTMLInputElement>(null); return <article className="vendor-document-card"><div className="vendor-document-card-head"><div><p className="vendor-eyebrow">{requirement.required ? 'Required' : 'Optional'}</p><h2>{requirement.label}</h2></div><span className={`document-status document-status-${document.status}`}>{document.status.replace('_', ' ')}</span></div>{document.fileName ? <p className="vendor-document-file">{document.fileName}<small>Uploaded {document.uploadedAt ? new Date(document.uploadedAt).toLocaleDateString('en-IN') : ''}</small></p> : <p className="vendor-document-missing">No document uploaded yet.</p>}{document.rejectionReason ? <p className="vendor-field-error">{document.rejectionReason}</p> : null}{requirement.expires ? <label className="vendor-document-expiry">Expiration date<input type="date" value={document.expiresAt?.slice(0, 10) ?? ''} readOnly placeholder="Set by verification team" /></label> : null}<input ref={inputRef} type="file" className="sr-only" accept=".pdf,.png,.jpg,.jpeg,.doc,.docx" onChange={(event) => { const file = event.target.files?.[0]; if (file) onUpload(file); event.target.value = '' }} /><button type="button" className="btn-skip" onClick={() => inputRef.current?.click()}>{document.fileName ? 'Replace document' : 'Upload document'}</button></article> }